import Mathlib
open Matrix NNReal BigOperators
def PureStrategyPayoff {m n : ℕ} (M : Matrix (Fin m) (Fin n) (ℝ × ℝ)) (p₁ : Fin m → ℝ≥0) (p₂ : Fin n → ℝ≥0) : ℝ × ℝ := (∑ i : Fin m, ∑ j : Fin n, p₁ i * p₂ j * (M i j).1, ∑ i : Fin m, ∑ j : Fin n, p₁ i * p₂ j * (M i j).2)
def IsPureNashEquilibrium {m n : ℕ} (M : Matrix (Fin m) (Fin n) (ℝ × ℝ)) (s₁ : Fin m → ℝ≥0) (s₂ : Fin n → ℝ≥0) : Prop := (∀ i, (∑ j : Fin n, s₂ j = 1) → ∀ j, (M i j).1 ≤ (M i j).1) ∧ (∀ j, (∑ i : Fin m, s₁ i = 1) → ∀ i, (M i j).2 ≤ (M i j).2)
def war_stage_payoff : Matrix (Fin 2) (Fin 2) (ℝ × ℝ) := !![(-5, -5), (-100, -100); (-100, -100), (-100, -100)]
theorem war_stage_nash_equilibria : let game := war_stage_payoff; let equilibria := { (s₁, s₂) | (s₁ = ![1, 0] ∧ s₂ = ![1, 0]) ∨ (s₁ = ![0, 1] ∧ s₂ = ![0, 1]) }; (∀ (s : _ × _), s ∈ equilibria → IsPureNashEquilibrium game s.1 s.2) ∧ (PureStrategyPayoff game ![1, 0] ![1, 0] = (-5, -5)) ∧ (PureStrategyPayoff game ![0, 1] ![0, 1] = (-100, -100)) := by sorry
